import { Environment, Lightformer } from '@react-three/drei'
import { Grid, OrbitControls, Stage } from '@react-three/drei'
import { useSearchParams } from '../useSearchParams'
import { NoirStreet } from './NoirStreet'
import { CameraRig } from './CameraRig'
import { ProceduralEnv } from './ProceduralEnv'
import { RenderProbe } from './RenderProbe'
import { Detective } from './Detective'
import { Props } from './Props'
import { Studio } from './Studio'
import { Turntable } from './Turntable'

const q = new URLSearchParams(location.search)
const MODE = q.get('scene') ?? 'street'
const time = parseFloat(q.get('t') ?? '0')

export function Scene() {
  const model = MODE === 'model' || q.has('model')
  const props = MODE === 'props' || q.has('props')

  if (props) {
    return (
      <>
        <Props
          name={q.get('prop') ?? 'car'}
          clip={q.get('clip') ?? undefined}
          time={time}
          probe={q.has('probe')}
        />
        <Turntable />
        <EnvFallback />
      </>
    )
  }

  if (model) {
    return (
      <>
        <Studio />
        <Detective
          clip={q.get('clip') ?? 'Idle'}
          time={time}
          rotationY={parseFloat(q.get('ry') ?? '0')}
          scale={parseFloat(q.get('scale') ?? '1')}
        />
        <Turntable />
        <CameraRig />
        <ProceduralEnv intensity={1.0} />
        <RenderProbe probe={q.has('probe')} />
      </>
    )
  }

  return (
    <>
      {/* ночная палитра Ноктиса: холодный лунный ключ + тёплые уличные фонари */}
      <color attach="background" args={['#0a0f1c']} />
      <fogExp2 attach="fog" args={['#131a2b', 0.0115]} />

      <ambientLight intensity={0.5} color="#6d8cc4" />
      <hemisphereLight args={['#8fb0e8', '#1a1c24', 0.55]} />
      <directionalLight
        castShadow
        position={[-14, 22, -10]}
        intensity={1.5}
        color="#b6cbf2"
        shadow-mapSize={[1536, 1536]}
        shadow-camera-near={1}
        shadow-camera-far={90}
        shadow-camera-left={-32}
        shadow-camera-right={32}
        shadow-camera-top={32}
        shadow-camera-bottom={-32}
        shadow-bias={-0.0006}
        shadow-normalBias={0.03}
      />

      <NoirStreet />
      {q.has('herob') && (
        <Detective
          clip={q.get('clip') ?? 'Idle'}
          time={time}
          position={[1.2, 0.18, 2]}
          rotationY={parseFloat(q.get('ry') ?? '0')}
        />
      )}
      <CameraRig />
      <ProceduralEnv intensity={1.1} />
      <RenderProbe probe={q.has('probe')} />
      <EnvFallback />
    </>
  )
}

function EnvFallback() {
  void Environment
  void Lightformer
  void Grid
  void OrbitControls
  void Stage
  void useSearchParams
  return null
}

import { useThree, useFrame } from '@react-three/fiber'
import { useEffect, useRef } from 'react'
import * as THREE from 'three'

export type CamSpec = {
  az: number
  el: number
  dist: number
  target: [number, number, number]
  fov: number
  /** параметры камеры заданы из URL — они главнее автокадрирования */
  manualDist: boolean
  manualTarget: boolean
  /** камеру ведёт turntable (?spin=), CameraRig уступает */
  turntable: boolean
}

/**
 * Камера, управляемая query-параметрами — чтобы рендерить кадры по сценарию:
 *   ?az=45&el=12&dist=9&ty=1.2&fov=40
 * Позволяет снимать одни и те же ракурсы детерминированно (для видео).
 */
function readSpec(): CamSpec {
  const q = new URLSearchParams(location.search)
  const n = (k: string, d: number) => {
    const v = parseFloat(q.get(k) ?? '')
    return Number.isFinite(v) ? v : d
  }
  return {
    az: n('az', 28),
    el: n('el', 10),
    dist: n('dist', 11),
    target: [n('tx', 0), n('ty', 1.4), n('tz', 0)],
    fov: n('fov', 42),
    manualDist: q.has('dist'),
    manualTarget: q.has('tx') || q.has('ty') || q.has('tz'),
    turntable: q.has('spin'),
  }
}

export function useCamSpec() {
  return useRef<CamSpec>(readSpec())
}

/**
 * `frame` — автокадрирование по габаритам модели (стенды `scene=props`):
 * если дистанция или цель не заданы из URL, берутся из bounding sphere.
 */
export function CameraRig({
  enabled = true,
  frame,
}: {
  enabled?: boolean
  frame?: { target: [number, number, number]; radius: number }
}) {
  const { camera } = useThree()
  const spec = useRef<CamSpec>(readSpec())
  const applied = useRef(false)

  useEffect(() => {
    const cam = camera as THREE.PerspectiveCamera
    cam.fov = spec.current.fov
    cam.updateProjectionMatrix()
  }, [camera])

  useFrame(({ gl }) => {
    if (!enabled || applied.current || spec.current.turntable) return
    applied.current = true
    const { az, el, fov, manualDist, manualTarget } = spec.current
    const fit = frame
      ? (frame.radius * 2.9) / (2 * Math.tan(THREE.MathUtils.degToRad(fov) / 2))
      : null
    const dist = manualDist || fit === null ? spec.current.dist : fit
    const target = manualTarget || !frame ? spec.current.target : frame.target
    const a = THREE.MathUtils.degToRad(az)
    const e = THREE.MathUtils.degToRad(el)
    const x = target[0] + dist * Math.cos(e) * Math.sin(a)
    const y = target[1] + dist * Math.sin(e)
    const z = target[2] + dist * Math.cos(e) * Math.cos(a)
    camera.position.set(x, y, z)
    camera.lookAt(target[0], target[1], target[2])
    const d = new THREE.Vector3()
    camera.getWorldDirection(d)
    document.title = `CAM pos=${camera.position.toArray().map((n) => n.toFixed(1))} dir=${d
      .toArray()
      .map((n) => n.toFixed(2))} drawCalls=${gl.info.render.calls} tris=${gl.info.render.triangles}`
  })

  return null
}

