import { useFrame, useThree } from '@react-three/fiber'
import { useMemo } from 'react'
import * as THREE from 'three'

const COUNT = 1500
const BOXY = 14
const AREA = { x: 22, z: 34 }
const FALL = 17
const WIND = 1.1
const OPACITY = 0.38

/** Дождь из точек вокруг игрока: обновляется на CPU, лишних лайтов нет.
 *  Точки растянуты по высоте — при быстром падении выглядят каплями-штрихами. */
export function Rain() {
  const camera = useThree((s) => s.camera)

  const { geom, alphas } = useMemo(() => {
    const pos = new Float32Array(COUNT * 3)
    const alpha = new Float32Array(COUNT)
    let seed = 17
    const rnd = () => {
      seed = (seed * 1103515245 + 12345) & 0x7fffffff
      return seed / 0x7fffffff
    }
    for (let i = 0; i < COUNT; i++) {
      pos[i * 3] = (rnd() * 2 - 1) * AREA.x
      pos[i * 3 + 1] = rnd() * BOXY
      pos[i * 3 + 2] = (rnd() * 2 - 1) * AREA.z
      alpha[i] = 0.35 + rnd() * 0.4
    }
    const g = new THREE.BufferGeometry()
    g.setAttribute('position', new THREE.BufferAttribute(pos, 3))
    g.setAttribute('aAlpha', new THREE.BufferAttribute(alpha, 1))
    g.computeBoundingSphere()
    return { geom: g, alphas: alpha }
  }, [])

  useFrame((_, dt) => {
    const step = Math.min(dt, 0.05)
    const attr = geom.getAttribute('position')
    const arr = attr.array as Float32Array
    const fall = FALL * step
    const wind = WIND * step
    for (let i = 0; i < COUNT; i++) {
      let y = arr[i * 3 + 1] - fall
      if (y < 0) y += BOXY
      arr[i * 3] -= wind
      if (arr[i * 3] < -AREA.x) arr[i * 3] += AREA.x * 2
      arr[i * 3 + 1] = y
    }
    attr.needsUpdate = true
    geom.computeBoundingSphere()
  })

  return (
    <points geometry={geom} frustumCulled={false}>
      <shaderMaterial
        depthWrite={false}
        transparent={true}
        blending={THREE.AdditiveBlending}
        vertexShader={`
          attribute float aAlpha;
          varying float vA;
          void main() {
            vA = aAlpha;
            vec4 mv = modelViewMatrix * vec4(position, 1.0);
            gl_PointSize = 220.0 / -mv.z;
            gl_Position = projectionMatrix * mv;
          }
        `}
        fragmentShader={`
          varying float vA;
          void main() {
            vec2 p = gl_PointCoord - vec2(0.5);
            float d = smoothstep(0.5, 0.16, length(p));
            gl_FragColor = vec4(vec3(0.62, 0.71, 0.85), d * vA);
          }
        `}
      />
    </points>
  )
}

import { useAnimations, useGLTF } from '@react-three/drei'
import { useFrame } from '@react-three/fiber'
import { useEffect, useMemo, useRef } from 'react'
import * as THREE from 'three'
import { clone as cloneSkeleton } from 'three/examples/jsm/utils/SkeletonUtils.js'

const TRAM = '/models/tram.glb'
const CAR = '/models/car.glb'
const DETECTIVE = '/models/detective.glb'
const Z_MIN = -44
const Z_MAX = 44

function useSeeded(seed: number) {
  return useMemo(() => {
    let s = seed
    return () => {
      s = (s * 1103515245 + 12345) & 0x7fffffff
      return s / 0x7fffffff
    }
  }, [seed])
}

/** Трамвай патрулирует улицу: без теней и лишних лайтов, но с анимацией хода. */
function Tram() {
  const { scene, animations } = useGLTF(TRAM)
  const { actions } = useAnimations(animations, scene)
  const ref = useRef<THREE.Group>(null)
  const z = useRef(-40)

  useEffect(() => {
    const a = actions.Run
    if (a) {
      a.reset()
      a.play()
      a.timeScale = 1
    }
    scene.traverse((o) => {
      o.castShadow = false
      o.receiveShadow = false
      o.frustumCulled = true
    })
  }, [actions, scene])

  useFrame((_, dt) => {
    z.current += 6.2 * Math.min(dt, 0.05)
    if (z.current > Z_MAX) z.current = Z_MIN
    const g = ref.current
    if (g) {
      g.position.set(0, 0.02, z.current)
      g.rotation.y = 0
    }
  })

  return (
    <group ref={ref} position={[0, 0.02, -40]}>
      <primitive object={scene} />
    </group>
  )
}

/** Служебная машина, которая едет по своей полосе. */
function Sedan({
  x,
  dir,
  speed,
  z0,
  siren,
}: {
  x: number
  dir: -1 | 1
  speed: number
  z0: number
  siren?: boolean
}) {
  const { scene, animations } = useGLTF(CAR)
  const { actions } = useAnimations(animations, scene)
  const ref = useRef<THREE.Group>(null)
  const z = useRef(z0)

  useEffect(() => {
    const a = actions[siren ? 'Siren' : 'Drive']
    if (a) {
      a.reset()
      a.play()
      a.timeScale = 1
    }
    scene.traverse((o) => {
      o.castShadow = false
      o.receiveShadow = false
      o.frustumCulled = true
    })
  }, [actions, scene, siren])

  useFrame((_, dt) => {
    z.current += dir * speed * Math.min(dt, 0.05)
    if (z.current > Z_MAX) z.current = Z_MIN
    if (z.current < Z_MIN) z.current = Z_MAX
    const g = ref.current
    if (g) {
      g.position.set(x, 0.02, z.current)
      g.rotation.y = dir > 0 ? 0 : Math.PI
    }
  })

  return (
    <group ref={ref} position={[x, 0.02, z0]}>
      <primitive object={scene} />
    </group>
  )
}

/** Прохожий: клон детектива с циклом Idle или Walk. */
function Pedestrian({
  x,
  dir = 1,
  speed = 1.2,
  z0,
  clip = 'Walk',
}: {
  x: number
  dir?: -1 | 1
  speed?: number
  z0: number
  clip?: 'Idle' | 'Walk' | 'Scan' | 'Point'
}) {
  const { scene, animations } = useGLTF(DETECTIVE)
  const clone = useMemo(() => cloneSkeleton(scene), [scene])
  const { actions } = useAnimations(animations, clone)
  const ref = useRef<THREE.Group>(null)
  const z = useRef(z0)

  useEffect(() => {
    const a = actions[clip]
    if (a) {
      a.reset()
      a.play()
      a.timeScale = 1.05
    }
    clone.traverse((o) => {
      o.castShadow = false
      o.frustumCulled = true
    })
  }, [actions, clip, clone])

  useFrame((_, dt) => {
    z.current += dir * speed * Math.min(dt, 0.05)
    if (z.current > Z_MAX) z.current = Z_MIN
    if (z.current < Z_MIN) z.current = Z_MAX
    const g = ref.current
    if (g) {
      g.position.set(x, 0.02, z.current)
      g.rotation.y = dir > 0 ? 0 : Math.PI
    }
  })

  return (
    <group ref={ref} position={[x, 0.02, z0]}>
      <primitive object={clone} />
    </group>
  )
}

/** Оживляет улицу: трамвай, две машины, прохожие. */
export function StreetLife() {
  const rnd = useSeeded(7)

  // статичные «зрители» на тротуарах — где именно стоять
  const bystanders = useMemo(
    () =>
      [0, 1, 2].map((i) => ({
        x: (rnd() > 0.5 ? 1 : -1) * (5.4 + rnd() * 1.6),
        z: -16 + (i * 14) + rnd() * 4,
        clip: (rnd() > 0.5 ? 'Scan' : 'Idle') as 'Scan' | 'Idle',
      })),
    [rnd],
  )

  const walkers = useMemo(
    () => [
      { x: 6.4, dir: -1 as const, z0: -20 },
      { x: -6.8, dir: 1 as const, z0: 30 },
    ],
    [],
  )

  return (
    <group>
      <Tram />
      <Sedan x={-2.7} dir={-1} speed={7.5} z0={26} />
      <Sedan x={2.7} dir={1} speed={6.2} z0={-30} siren />
      {walkers.map((w, i) => (
        <Pedestrian key={`w${i}`} x={w.x} dir={w.dir} z0={w.z0} />
      ))}
      {bystanders.map((b, i) => (
        <Pedestrian key={`b${i}`} x={b.x} z0={b.z} clip={b.clip} speed={0} />
      ))}
    </group>
  )
}

import { useMemo } from 'react'
import * as THREE from 'three'

type Item = {
  kind: 'bin' | 'crate' | 'hydrant' | 'box'
  x: number
  z: number
  rot: number
  s: number
}

function seedTable(seed: number, n: number, pads: { x: number; z: number }[]) {
  let s = seed
  const rnd = () => {
    s = (s * 1103515245 + 12345) & 0x7fffffff
    return s / 0x7fffffff
  }
  const kinds: Item['kind'][] = ['bin', 'crate', 'box', 'hydrant', 'crate', 'bin', 'box']
  const out: Item[] = []
  for (let i = 0; i < n; i++) {
    const side = rnd() > 0.5 ? 1 : -1
    const nearCurb = rnd() > 0.5
    out.push({
      kind: kinds[i % kinds.length],
      x: side * (nearCurb ? 7.0 + rnd() * 1.4 : 9.2 + rnd() * 2.2),
      z: pads[i % pads.length].z,
      rot: rnd() * Math.PI * 2,
      s: 0.85 + rnd() * 0.5,
    })
  }
  return out
}

/** Набор уличной мелочи на тротуарах: баки, ящики, гидрант. Без новых лайтов. */
export function StreetProps() {
  const pads = useMemo(
    () => [
      { x: 1, z: -20 },
      { x: 1, z: -13 },
      { x: 1, z: -6 },
      { x: 1, z: 2 },
      { x: 1, z: 9 },
      { x: 1, z: 16 },
    ],
    [],
  )

  const props = useMemo(() => seedTable(99, 16, pads), [pads])
  const hydrants = props.filter((p) => p.kind === 'hydrant')
  const bins = props.filter((p) => p.kind === 'bin')
  const crates = props.filter((p) => p.kind === 'crate' || p.kind === 'box')

  const list = (items: Item[], color: string) =>
    items.map((p, i) => (
      <mesh
        key={`${i}-${p.kind}`}
        position={[p.x, 0.02, p.z]}
        rotation={[0, p.rot, 0]}
        scale={p.s}
        castShadow
      >
        <boxGeometry args={[0.24, 0.34, 0.24]} />
        <meshStandardMaterial color={color} roughness={0.9} metalness={0.05} />
      </mesh>
    ))

  return (
    <group>
      {list(bins, '#2a2e38')}
      {list(crates, '#4a3620')}
      {hydrants.map((p, i) => (
        <group
          key={`h${i}`}
          position={[p.x, 0.02, p.z]}
          rotation={[0, p.rot, 0]}
          scale={p.s}
        >
          <mesh castShadow>
            <cylinderGeometry args={[0.09, 0.09, 0.34, 12]} />
            <meshStandardMaterial color="#8d2b1d" roughness={0.6} metalness={0.3} />
          </mesh>
          <mesh position={[0, 0.17, 0]} castShadow>
            <cylinderGeometry args={[0.055, 0.055, 0.12, 10]} />
            <meshStandardMaterial color="#8d2b1d" roughness={0.6} metalness={0.3} />
          </mesh>
        </group>
      ))}
    </group>
  )
}

