```java
package com.sj0404.noirdet;

import java.util.regex.*;

public final class Version {
    public static int[] parse(String tag) {
        // "v0.3.0" -> [0,3,0]
        Matcher m = Pattern.compile("v?(\\d+)(?:\\.(\\d+))?(?:\\.(\\d+))?").matcher(tag.trim());
        if (!m.find()) return new int[]{-1};
        int[] v = new int[3];
        for (int i = 0; i < 3; i++) {
            String g = m.group(1 + i);
            v[i] = g == null ? 0 : Integer.parseInt(g);
        }
        return v;
    }
    /** >0 если a новее b, <0 если младше, 0 равны */
    public static int compare(String a, String b) {
        int[] va = parse(a), vb = parse(b);
        for (int i = 0; i < 3; i++) {
            if (va[i] != vb[i]) return va[i] - vb[i];
        }
        return 0;
    }
}
